import{_ as i,c as a,o as e,af as t}from"./chunks/framework.CpuDhtGM.js";const p=JSON.parse('{"title":"成长空间","description":"","frontmatter":{},"headers":[],"relativePath":"value-investing/business-model/growth.md","filePath":"value-investing/business-model/growth.md","lastUpdated":1765875817000}'),o={name:"value-investing/business-model/growth.md"};function r(u,l,n,s,h,d){return e(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="成长空间" tabindex="-1">成长空间 <a class="header-anchor" href="#成长空间" aria-label="Permalink to &quot;成长空间&quot;">​</a></h1><h2 id="企业成长空间分析" tabindex="-1">企业成长空间分析 <a class="header-anchor" href="#企业成长空间分析" aria-label="Permalink to &quot;企业成长空间分析&quot;">​</a></h2><h3 id="一、​-好成长-与-坏成长" tabindex="-1">一、​“好成长”与“坏成长” <a class="header-anchor" href="#一、​-好成长-与-坏成长" aria-label="Permalink to &quot;一、​“好成长”与“坏成长”&quot;">​</a></h3><p>坏成长：</p><ol><li>加杠杆背负债务风险来迅速扩张。</li><li>通过眼花缭乱的并购来促进成长。（商誉暴雷）</li><li>通过不断加大资本支出甚至不惜牺牲回报率来促进成长。</li><li>通过恶性多元化来促进成长。</li><li>通过铺天盖地的营销而非产品的口碑来促进成长</li><li>不在乎盈利只追求规模迅速扩大，吸引更多资本。</li><li>为了迎合股市，放松风险控制，饮鸩止渴的增长。</li><li>不惜通过财务腾挪造假来制造的增长。</li></ol><p>拥有“好成长”的公司，业绩反而是不需要每年、每季度都增长的。企业的发展绝不是线性的，而是在波折中前进的，这才是正常的。</p><h3 id="二、商业模式决定企业的市场规模" tabindex="-1">二、商业模式决定企业的市场规模 <a class="header-anchor" href="#二、商业模式决定企业的市场规模" aria-label="Permalink to &quot;二、商业模式决定企业的市场规模&quot;">​</a></h3><ol><li>目标客户范围的大小</li><li>使用场景的广泛度</li><li>产品购买频次</li><li>价格的高低</li><li>可标准化与可复制性</li></ol><p>需要注意，某一家企业的发展空间有多大，未必是其所在的行业整体空间那么大。</p><h3 id="三、企业的发展阶段决定着成长空间" tabindex="-1">三、企业的发展阶段决定着成长空间 <a class="header-anchor" href="#三、企业的发展阶段决定着成长空间" aria-label="Permalink to &quot;三、企业的发展阶段决定着成长空间&quot;">​</a></h3><ul><li>“成长空间”不等同于“市场规模”​</li><li><strong>对投资而言，企业发展的相对空间比绝对空间更有意义</strong></li><li>海阔凭鱼跃，天高任鸟飞。​”往往市场规模巨大的行业才能产生一些发展空间大的公司。非常狭小的市场，很难养几家发展空间大的公司，而且企业很快会遇到天花板。所以，​“绝对空间”很大程度上决定着“相对空间”的大小。</li><li>企业的成长空间主要由企业所在的发展阶段决定。</li></ul><h3 id="四、企业的成长动力分解" tabindex="-1">四、企业的成长动力分解 <a class="header-anchor" href="#四、企业的成长动力分解" aria-label="Permalink to &quot;四、企业的成长动力分解&quot;">​</a></h3><p>增加收入、提高毛利率、降低费用率</p><ul><li>净利润增长 <ul><li>营收增长 <ul><li>销量增长 <ul><li>市场规模增长</li><li>市场份额提高</li><li>拓展新的市场</li><li>开发新的产品和业务</li></ul></li><li>价格提高 <ul><li>产品提价</li><li>产品结构升级</li></ul></li><li>外延并购</li></ul></li><li>净利润率提高 <ul><li>毛利率提高 <ul><li>产品提价</li><li>降低生产成本</li></ul></li><li>费用率降低 <ul><li>降低管理费用率</li><li>降低财务费用率</li><li>降低营销费用率</li></ul></li></ul></li></ul></li></ul><h3 id="五、洞察经济社会发展趋势" tabindex="-1">五、洞察经济社会发展趋势 <a class="header-anchor" href="#五、洞察经济社会发展趋势" aria-label="Permalink to &quot;五、洞察经济社会发展趋势&quot;">​</a></h3><p>为了理解一个行业、一家企业的发展前景，我们需要对经济、科技、商业、社会、政治、人口结构、人们的行为习惯等大的社会趋势有仔细的观察。社会的大趋势不是我们投资决策的主要依据，但会影响到企业的长期前景。从价格层面考虑，投资要逆向。但从企业发展前景来讲，好的投资机会大部分是处在顺应经济社会发展趋势的行业中。逆风的行业，大部分企业的日子比较难过。</p><ul><li><ol><li>供给侧改革、消费升级和城镇化</li></ol><ul><li>供给侧改革，不仅仅是为落后产能做减法，更重要的是做加法。从生产领域加强优质供给，减少无效供给，扩大有效供给。</li><li>消费升级是多层次的，螺旋上升的。</li></ul></li><li><ol start="2"><li>技术变化的速度不断加快</li></ol><ul><li>新技术刚出现时，企业的竞争格局尚不明朗，大量资本涌入，竞争激烈。</li><li>作为投资者，即使不投资科技股，我们也一定要对新的科技趋势保持高度敏感的关注。</li></ul></li><li><ol start="3"><li>年轻人成为消费主力军</li></ol><ul><li>消费理念超前、互联网原住民、喜欢偷懒、爱分享爱表达、个性化、喜欢尝试新鲜事物</li></ul></li><li><ol start="4"><li>人口结构和老龄化</li></ol><ul><li>医药产业、医疗服务、保险公司、养老服务产业</li></ul></li></ul><h3 id="六、缓慢增长行业也可能有很好的投资机会" tabindex="-1">六、缓慢增长行业也可能有很好的投资机会 <a class="header-anchor" href="#六、缓慢增长行业也可能有很好的投资机会" aria-label="Permalink to &quot;六、缓慢增长行业也可能有很好的投资机会&quot;">​</a></h3><p>做到别人不容易做到的，才是真正的英雄。如果在缓慢增长的行业获得高速增长，一般说明公司有非常大的竞争优势。</p><p>行业慢速发展对小天鹅、海尔反而是好事情。相反，在行业高速增长的阶段，小天鹅的日子其实反而更难过。2001—2002 年期间，洗衣机行业大幅增长，但由于竞争激烈价格大幅下滑、原材料价格上涨，导致业内大部分公司亏损，小天鹅也出现亏损。</p><p>——《投资至简：从原点出发构建价值投资体系》第二章 第三节 企业成长空间分析</p>',21)])])}const _=i(o,[["render",r]]);export{p as __pageData,_ as default};
